  IEnumerator PhysicalCases(){m.ProbeHandsOff=true;yield return new WaitForSecondsRealtime(4);foreach(var ped in m.Crowd)ped.ragdoll.PrepareForPool();for(int i=0;i<8;i++)m.trucks[i].Park(new Vector3(-65+i*3,2,65));Vector3 center=new Vector3(-24,.05f,-24);int[] ids={0,1,2,3,4,5};
   PlowPedestrian p=m.Crowd[ids[0]];p.ResetTarget(m,p.id,p.role,center,Quaternion.identity,p.characterName,p.panicLine);p.agent.enabled=false;
   m.trucks[0].Prepare(center+Vector3.back*5+Vector3.up*.65f,Quaternion.identity);m.trucks[0].body.linearVelocity=Vector3.forward*1.5f;int before=m.Round.AwardCount;yield return new WaitForSecondsRealtime(3);Check(m.Round.AwardCount==before,"slow actual approach does not score");p.ragdoll.PrepareForPool();m.trucks[0].Park(new Vector3(-65,2,65));
   p=m.Crowd[ids[1]];p.ResetTarget(m,p.id,p.role,center,Quaternion.identity,p.characterName,p.panicLine);p.agent.enabled=false;m.trucks[0].Prepare(center+Vector3.back*5+Vector3.up*.65f,Quaternion.identity);m.trucks[0].body.linearVelocity=Vector3.forward*10;int score=m.Round.Score(0);yield return new WaitForSecondsRealtime(1.5f);Check(m.Round.Owner(p.id)==0&&m.Round.Score(0)==score+PlowRound.Points(p.role),"real PhysX truck hit awards correct role once");Check(p.ragdoll.IsRagdoll&&(!p.useDistanceRendering||!p.presentationLOD.enabled&&!p.distanceModel.enabled),"genuine physical impact restores full detailed jointed ragdoll");int awarded=m.Round.AwardCount;yield return new WaitForSecondsRealtime(2);Check(m.Round.AwardCount==awarded,"continued ragdoll contacts never repeat score");m.trucks[0].Park(new Vector3(-65,2,65));p.ragdoll.PrepareForPool();
   p=m.Crowd[ids[2]];p.ResetTarget(m,p.id,p.role,center,Quaternion.identity,p.characterName,p.panicLine);p.agent.enabled=false;m.trucks[0].Prepare(center+Vector3.back*7+Vector3.up*.65f,Quaternion.identity);m.trucks[1].Prepare(center+Vector3.forward*4+Vector3.up*.65f,Quaternion.Euler(0,180,0));m.trucks[0].body.linearVelocity=Vector3.forward*10;m.trucks[1].body.linearVelocity=Vector3.back*10;before=m.Round.AwardCount;yield return new WaitForSecondsRealtime(1.7f);Check(m.Round.AwardCount==before+1&&m.Round.Owner(p.id)==1,"first physical arrival wins independent of slot order");m.trucks[0].Park(new Vector3(-65,2,65));m.trucks[1].Park(new Vector3(-62,2,65));p.ragdoll.PrepareForPool();
   p=m.Crowd[ids[3]];p.ResetTarget(m,p.id,p.role,center,Quaternion.identity,p.characterName,p.panicLine);p.agent.enabled=false;m.trucks[0].Prepare(center+Vector3.back*4+Vector3.up*.65f,Quaternion.identity);m.trucks[1].Prepare(center+Vector3.forward*4+Vector3.up*.65f,Quaternion.Euler(0,180,0));m.trucks[0].body.linearVelocity=Vector3.forward*10;m.trucks[1].body.linearVelocity=Vector3.back*10;before=m.Round.AwardCount;yield return new WaitForSecondsRealtime(1.5f);Check(m.Round.AwardCount==before+1&&m.Round.Owner(p.id)>=0,"simultaneous physical impact has exactly one owner");
   var prop=m.props[0];prop.ResetProp();prop.body.position=center+Vector3.forward*8;Physics.SyncTransforms();m.trucks[0].Prepare(center+Vector3.forward*2+Vector3.up*.65f,Quaternion.identity);m.trucks[0].body.linearVelocity=Vector3.forward*12;yield return new WaitForSecondsRealtime(1.5f);Check(prop.breakable!=null&&prop.breakable.HasCollapsed,"real truck impact breaks Core-Collapse prop");prop.ResetProp();Check(!prop.breakable.HasCollapsed&&prop.body.detectCollisions,"pooled breakable restores on reset");
   m.Round.Advance(m.Round.Duration);yield return new WaitForFixedUpdate();Check(m.Finished,"duration seals physical round");int finalAwards=m.Round.AwardCount;yield return new WaitForSecondsRealtime(.5f);Check(m.Round.AwardCount==finalAwards,"post-result contacts cannot score");yield return Capture("physical-fixtures");yield return ReplayCases();m.ProbeHandsOff=false;
  }
  IEnumerator CabCases(){Check(m is PlowCabMatch&&m.cabExperience&&m.option==2,"separate Cab Chaos entry forces first person");var pads=new Gamepad[4];m.SetupScreen();for(int i=0;i<4;i++){pads[i]=InputSystem.AddDevice<Gamepad>();m.setup.players[i].source=BowlingSource.WholeController;m.setup.players[i].pad=pads[i];}m.setup.count=8;m.StartMatch();yield return new WaitForSecondsRealtime(4.5f);Check(m.cameras.Length==4,"four independent cab views");for(int i=0;i<4;i++){Check(m.cabExtras.gps[i].follow==m.trucks[i].transform&&m.cabExtras.gps[i].cameraMain==m.cameras[i],"GPS owner "+i);Check(m.cabExtras.gps[i].canvas.renderMode==RenderMode.WorldSpace,"real vendor world-space GPS "+i);}Check(FindObjectsByType<AudioListener>().Length==1,"one listener with four dashboard GPS displays");
   InputSystem.QueueStateEvent(pads[0],new GamepadState{leftStick=new Vector2(.3f,0),rightTrigger=.65f});yield return new WaitForSecondsRealtime(.5f);Check(m.trucks[0].command.x>.1f&&m.trucks[0].command.y>.1f,"injected pad drives NWH truck");Check(Mathf.Abs(m.views.rally.views[0].cabSteering.CurrentAngle)>10,"actual steering wheel follows NWH angle");
   InputSystem.QueueStateEvent(pads[0],new GamepadState().WithButton(GamepadButton.LeftShoulder));yield return new WaitForSecondsRealtime(.25f);Check(m.cabExtras.needs[0].JugActive&&!m.cabExtras.needs[1].JugActive,"jug input starts only owning driver's Taxi state");
   m.Pause();float elapsed=m.cabExtras.needs[0].JugElapsed,pressure=m.cabExtras.needs[0].Pressure;yield return new WaitForSecondsRealtime(.3f);Check(m.cabExtras.needs[0].JugElapsed==elapsed&&m.cabExtras.needs[0].Pressure==pressure,"pause preserves jug challenge and pressure");InputSystem.QueueStateEvent(pads[0],new GamepadState());m.Resume();yield return null;yield return null;
   InputSystem.DisableDevice(pads[1]);yield return null;Check(m.Paused&&Time.timeScale==0,"disconnect pauses all physical bodies without losing state");var replacement=InputSystem.AddDevice<Gamepad>();Check(m.Assign(1,replacement),"explicit independent controller replacement");m.Resume();yield return new WaitForSecondsRealtime(.2f);Check(m.Live,"replacement resumes existing cab match");
   foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)}){Screen.SetResolution(size.x,size.y,false);yield return new WaitForSecondsRealtime(.3f);yield return Capture("cab-four-"+size.x);}
   m.ProbeHandsOff=true;foreach(var t in m.trucks)if(t.gameObject.activeSelf)t.body.linearVelocity=Vector3.zero;
   var n=m.cabExtras.needs[0];n.CancelJug();n.SetPressure(.55f);InputSystem.QueueStateEvent(pads[0],new GamepadState());yield return new WaitForSecondsRealtime(.2f);int successes=n.SuccessfulJugs,spills=n.Spills;
   InputSystem.QueueStateEvent(pads[0],new GamepadState().WithButton(GamepadButton.LeftShoulder));yield return null;yield return null;float deadline=Time.realtimeSinceStartup+12;bool tap=false;while(n.JugActive&&Time.realtimeSinceStartup<deadline){bool cue=n.CueIsOpen(m.trucks[0].body.linearVelocity.magnitude>1);var state=new GamepadState().WithButton(GamepadButton.LeftShoulder);if(cue&&!tap)state=state.WithButton(GamepadButton.RightShoulder);InputSystem.QueueStateEvent(pads[0],state);tap=cue&&!tap;yield return null;}Check(n.SuccessfulJugs==successes+1&&n.Spills==spills,"injected timed Taxi jug three-cue success");
   InputSystem.QueueStateEvent(pads[0],new GamepadState());yield return new WaitForSecondsRealtime(.2f);n.SetPressure(.55f);InputSystem.QueueStateEvent(pads[0],new GamepadState().WithButton(GamepadButton.LeftShoulder));yield return new WaitForSecondsRealtime(.1f);InputSystem.QueueStateEvent(pads[0],new GamepadState());yield return new WaitForSecondsRealtime(1);Check(n.Spills==spills+1&&n.CabMess,"early release genuinely spills owning jug");
   for(int i=0;i<4;i++){var gps=m.cabExtras.gps[i];var fit=gps.GetComponent<PlowCabGpsFit>();Check(fit!=null&&fit.screen.sizeDelta==new Vector2(640,340)&&fit.screen.localPosition.sqrMagnitude>.1f,"physical dashboard screen fitted "+i);}
   InputSystem.QueueStateEvent(pads[0],new GamepadState());yield return new WaitForSecondsRealtime(.2f);InputSystem.QueueStateEvent(pads[0],new GamepadState{rightStick=new Vector2(.8f,0)});yield return new WaitForSecondsRealtime(.45f);var look=m.views.rally.views[0].GetComponent<SportsCabLook>();Check(look.Yaw>5&&Quaternion.Angle(m.cameras[0].transform.rotation,m.views.cabRoots[0].rotation)>5,"free look turns driver's head independently of physical cab");yield return Capture("cab-free-look");InputSystem.QueueStateEvent(pads[0],new GamepadState().WithButton(GamepadButton.RightStick));yield return new WaitForSecondsRealtime(.1f);InputSystem.QueueStateEvent(pads[0],new GamepadState());yield return new WaitForSecondsRealtime(1);log.AppendLine("LOOK yaw at1s="+look.Yaw+" realtime="+Time.realtimeSinceStartup);Check(Mathf.Abs(look.Yaw)<1,"owning driver's look recenters");yield return new WaitForSecondsRealtime(1);log.AppendLine("LOOK yaw at2s="+look.Yaw);Check(Mathf.Abs(look.Yaw)<1,"recenter observation after2s");
   m.ProbeHandsOff=false;m.SetupScreen();foreach(var pad in pads)InputSystem.RemoveDevice(pad);InputSystem.RemoveDevice(replacement);
  }
  IEnumerator ReplayCases(){int count=m.Round.AwardCount;var replay=m.GetComponent<SportsMotionReplay>();Check(replay!=null&&replay.Duration>.1f,"actual physical impact recorded");if(replay==null||replay.Duration<=.1f)yield break;m.ExtraAction("highlights");yield return null;Check(m.ReplayControls,"optional results highlight starts");Check(!m.trucks[0].paint.enabled&&replay.ghosts[0].GetComponentsInChildren<Collider>(true).Length==0&&replay.ghosts[0].GetComponentsInChildren<MonoBehaviour>(true).Length==0,"replay hides live vehicles and ghosts have no physics or gameplay");float[] speeds={2,.25f,.5f};for(int angle=0;angle<3;angle++){m.ExtraAction("replayrewind");m.ExtraAction("replayangle");m.ExtraAction("replayspeed");yield return new WaitForSecondsRealtime(.2f);Check(m.ReplayControls&&replay.Angle==angle+1&&replay.Speed==speeds[angle],"recorded alternate camera / speed "+angle);var camera=m.views.rally.broadcast.view;Check(!camera.orthographic&&m.cameras.Length==1&&m.cameras[0]==camera&&Vector3.Distance(camera.transform.position,replay.Position(1))<65,"rendered replay perspective and close framing "+angle);yield return Capture("replay-angle-"+angle);}m.ExtraAction("replayspeed");Check(replay.Speed==1,"replay slow/normal/fast returns to normal");m.ExtraAction("replayskip");Check(!m.ReplayControls&&m.Finished&&m.Round.AwardCount==count&&m.trucks[0].paint.enabled,"skip restores sealed results without scoring");}
